<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/ranked.php';pv_require_login();$db=pv_db();
$actions=[''=>'All activity','wild'=>'Wild battles','ranked'=>'Ranked battles','materialize'=>'Materialization','party'=>'Party changes','digivolve'=>'Digivolution','training'=>'Training','shop'=>'Shop visits','reward'=>'Season rewards'];$filter=(string)($_GET['activity']??'');if(!isset($actions[$filter]))$filter='';$page=max(1,min(1000,(int)($_GET['page']??1)));$offset=($page-1)*30;
$where=$filter!==''?' WHERE a.action=?':'';$params=$filter!==''?[$filter]:[];
$total=(int)dn_row($db,'SELECT COUNT(*) n FROM nxt_bot_activity a'.$where,$params)['n'];$pages=max(1,(int)ceil($total/30));$page=min($page,$pages);$offset=($page-1)*30;
$feed=dn_rows($db,'SELECT a.*,m.username,m.created_avatar,b.bot_no FROM nxt_bot_activity a JOIN members m ON m.id=a.owner_id JOIN nxt_bots b ON b.owner_id=a.owner_id'.$where.' ORDER BY a.id DESC LIMIT 30 OFFSET '.$offset,$params);
$stats=dn_row($db,'SELECT COUNT(*) tamers,SUM(last_active>?) active,SUM(wild_wins) wild_wins,SUM(wild_losses) wild_losses,SUM(materialized) materialized,SUM(party_changes) party_changes,SUM(evolutions) evolutions FROM nxt_bots',[time()-900]);$ranked=dn_row($db,'SELECT COALESCE(SUM(p.wins),0) wins,COALESCE(SUM(p.losses),0) losses FROM nxt_ranked_profiles p JOIN nxt_bots b ON b.owner_id=p.owner_id');$worker=dn_row($db,"SELECT * FROM nxt_worker_state WHERE worker_key='tamers'");$running=$worker&&(int)$worker['last_run']>time()-90;$problem=!empty($worker['last_error']);$daemon=dn_row($db,"SELECT last_run FROM nxt_worker_state WHERE worker_key='tamers_daemon'");$background=(int)($daemon['last_run']??0)>time()-90;
pv_page_start('AI Activity','ai_activity.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('ai_activity.php');?><main class="pv-main-column"><section class="pv-page bp-page"><header class="bp-hero"><div><span class="pv-eyebrow">THE TAMER NETWORK</span><h1>A world that keeps moving.</h1><p>Follow <?=number_format((int)$stats['tamers'])?> autonomous tamers as they battle, scan new partners and build their teams.</p><nav class="bp-tabs" aria-label="Battle Park"><a href="<?=pv_h(pv_url('battle_arena.php'))?>">Battle Park</a><a href="<?=pv_h(pv_url('tamer_rivals.php'))?>">Tamer rivals</a><a class="active" href="<?=pv_h(pv_url('ai_activity.php'))?>">AI activity</a></nav></div><div class="bp-worker <?=$running&&!$problem?'is-running':''?>"><i></i><strong><?=$problem?'ACTIVITY NEEDS ATTENTION':($running?'TAMERS ACTIVE':'STARTING TAMERS')?></strong><small><?=$problem?'Some turns could not finish. Check the server log.':($worker?'Last update '.gmdate('H:i:s',(int)$worker['last_run']).' UTC':'Connecting automatically…')?></small></div></header>
<p class="bp-fine" data-tamer-mode><?=$background?'Background worker connected · tamers keep playing with no players online.':'Browser activity connects automatically · install the background worker to keep tamers active with every browser closed.'?></p><noscript><p class="pv-flash error">Enable JavaScript for automatic browser activity, or install the background worker for continuous activity.</p></noscript>
<div class="bp-stats"><article><span>EXPLORING NOW</span><strong><?=number_format((int)$stats['active'])?></strong><small>Active in the last 15 minutes</small></article><article><span>WILD BATTLES</span><strong><?=number_format((int)$stats['wild_wins'])?><i> W</i></strong><small><?=number_format((int)$stats['wild_losses'])?> losses · every result earned in battle</small></article><article><span>RANKED BATTLES</span><strong><?=number_format((int)$ranked['wins'])?><i> W</i></strong><small><?=number_format((int)$ranked['losses'])?> losses against players and AI tamers</small></article><article><span>NEW PARTNERS</span><strong><?=number_format((int)$stats['materialized'])?></strong><small><?=number_format((int)$stats['evolutions'])?> evolutions · <?=number_format((int)$stats['party_changes'])?> party changes</small></article></div>
<section class="bp-card"><div class="bp-section-title"><div><span class="pv-eyebrow">RECORDED ADVENTURES</span><h2>On the network</h2></div><form method="get" class="bp-filter"><label class="sr-only" for="activity-filter">Filter activity</label><select name="activity" id="activity-filter"><?php foreach($actions as $key=>$label):?><option value="<?=pv_h($key)?>" <?=$filter===$key?'selected':''?>><?=pv_h($label)?></option><?php endforeach;?></select><button class="bp-secondary">Show</button></form></div>
<?php if(!$feed):?><div class="pv-empty">No adventures in this view yet. The first completed action will appear here.</div><?php endif;?><div class="bp-feed"><?php foreach($feed as $row):$detail=json_decode($row['detail_json'],true)?:[];$result=(string)($detail['result']??'');?><article><div class="bp-feed-avatar"><img src="<?=pv_h(nxt_skin_url((int)$row['created_avatar']))?>" alt=""></div><div class="bp-feed-copy"><div><span class="bp-badge is-ai">AI TAMER</span><strong><?=pv_h($row['username'])?></strong><time datetime="<?=gmdate('c',(int)$row['created_at'])?>"><?=gmdate('d M · H:i:s',(int)$row['created_at'])?> UTC</time></div><h3><?=pv_h($row['summary'])?></h3><p><?php if($row['action']==='wild'):?><span class="bp-outcome <?=pv_h($result)?>"><?=strtoupper($result)?></span> <span>+<?=(int)($detail['scan']??0)?>% scan · +<?=(int)($detail['exp']??0)?> team EXP · +<?=(int)($detail['bits']??0)?> Bits</span><?php elseif($row['action']==='ranked'):?><span class="bp-outcome <?=pv_h($result)?>"><?=strtoupper($result)?></span> <span>vs <?=pv_h((string)($detail['opponent']??'Rival'))?> · <?=(int)($detail['points_before']??0)?> → <?=(int)($detail['points_after']??0)?> points</span><?php elseif($row['action']==='materialize'):?>100%+ scan converted into an owned Digimon.<?php elseif($row['action']==='party'):?>The new formation is ready for exploration and Battle Park.<?php elseif($row['action']==='digivolve'):?>Partner growth · ABI <?=(int)($detail['abi']??0)?><?php elseif($row['action']==='training'):?>A real stat-training point added to this partner.<?php else:?>Recorded after the action completed.<?php endif;?></p><?php if(!empty($detail['log'])):?><details class="bp-feed-log"><summary>Battle highlights</summary><ol><?php foreach($detail['log'] as $line):?><li><?=pv_h((string)$line)?></li><?php endforeach;?></ol></details><?php endif;?></div></article><?php endforeach;?></div><nav class="bp-pager" aria-label="Activity pages"><?php if($page>1):?><a href="?<?=pv_h(http_build_query(['activity'=>$filter,'page'=>$page-1]))?>">← Newer</a><?php endif;?><span>Page <?=$page?> of <?=$pages?></span><?php if($page<$pages):?><a href="?<?=pv_h(http_build_query(['activity'=>$filter,'page'=>$page+1]))?>">Older →</a><?php endif;?></nav></section>
<p class="bp-fine bp-note">Updates after completed activity and every 15 seconds while this page is visible. This feed shows completed actions from persistent tamer accounts. Battles use the same combat rules as yours. Tamers earn scan data, materialize partners, train, digivolve and change formation as their adventures progress.</p></section></main></div><script defer src="<?=pv_h(pv_asset('js/network-live.js'))?>?v=<?=pv_asset_version()?>"></script><?php pv_page_end();?>
